import { bind } from "@react-rxjs/core"
import { normalizeAddress } from "@taostats-wallet/crypto"
import {
  Account,
  isAccountNotContact,
  isAccountOfType,
  isAccountOwned,
  isAccountPortfolio,
  Trees,
} from "extension-core"
import { map, Observable, shareReplay } from "rxjs"

import { api } from "@ui/api"

import { debugObservable } from "./util/debugObservable"

export const accounts$ = new Observable<Account[]>((subscriber) => {
  const unsubscribe = api.accountsSubscribe((accounts) => {
    subscriber.next(accounts)
  })
  return () => unsubscribe()
}).pipe(debugObservable("accounts$"), shareReplay(1))

export const accountsCatalog$ = new Observable<Trees>((subscriber) => {
  const unsubscribe = api.accountsCatalogSubscribe((trees) => {
    subscriber.next(trees)
  })
  return () => unsubscribe()
}).pipe(debugObservable("accountsCatalog$"), shareReplay(1))

export const [useAccountsCatalog] = bind(accountsCatalog$)

export const accountsMap$ = accounts$.pipe(
  map((accounts) =>
    Object.fromEntries(accounts.map((account) => [normalizeAddress(account.address), account])),
  ),
)

export const [useAccountsMap] = bind(accountsMap$)

export const [useAccountByAddress, getAccountByAddress$] = bind(
  (address: string | null | undefined) =>
    accountsMap$.pipe(
      map((accountsMap) => {
        if (!address) return null
        const normalizedAddress = normalizeAddress(address)
        return accountsMap[normalizedAddress] ?? null
      }),
    ),
)

export type AccountCategory =
  | "all"
  | "watched"
  | "owned"
  | "portfolio"
  | "signet"
  | "all-except-contacts"

export const [useAccounts, getAccountsByCategory$] = bind(
  (category: AccountCategory = "all-except-contacts") =>
    accounts$.pipe(
      map((accounts) => {
        switch (category) {
          case "portfolio":
            return accounts.filter(isAccountPortfolio)
          case "watched":
            return accounts.filter((acc) => isAccountOfType(acc, "watch-only"))
          case "owned":
            return accounts.filter(isAccountOwned)
          case "signet":
            return accounts.filter((acc) => isAccountOfType(acc, "signet"))
          case "all-except-contacts":
            return accounts.filter(isAccountNotContact)
          case "all":
            return accounts
        }
      }),
    ),
)
