const isDecryptRequest = request => {
  return request.type !== undefined && request.type === ENCRYPT_DECRYPT_PREFIX;
};

const fetchFromCoingecko = async (relativeUrl, init = {}) => {
  const coingecko = await remoteConfigStore.get("coingecko");
  const headers = coingecko.apiKeyName && coingecko.apiKeyValue ? {
    [coingecko.apiKeyName]: coingecko.apiKeyValue
  } : {};
  const enhancedInit = merge(init, {
    headers
  });
  return fetch(urlJoin(coingecko.apiUrl, relativeUrl), enhancedInit);
};

const assetPlatformCache = {
  data: [],
  fetched: undefined
};
const ASSETPLATFORM_CACHE_TIMEOUT = 10 * 60 * 1000; // 10 minutes

const getCoinGeckoAssetPlatform = async (assetPlatformId, signal) => {
  if (!assetPlatformCache.fetched || assetPlatformCache.fetched + ASSETPLATFORM_CACHE_TIMEOUT < Date.now()) {
    try {
      const fetchAssetPlaforms = await fetchFromCoingecko("/api/v3/asset_platforms", {
        signal
      });
      if (fetchAssetPlaforms.ok) {
        assetPlatformCache.data = await fetchAssetPlaforms.json();
        assetPlatformCache.fetched = Date.now();
      }
    } catch (error) {
      log.error("Unable to fetch coingecko asset platforms ", {
        error
      });
    }
  }
  if (!assetPlatformCache.data || assetPlatformCache.data.length === 0) return null;
  return assetPlatformCache.data.find(({
    id,
    chain_identifier
  }) => [id, chain_identifier?.toString()].filter(isTruthy).includes(assetPlatformId)) ?? null;
};
const getCoinGeckoErc20Coin = async (assetPlatformId, contractAddress, signal) => {
  const assetPlatform = await getCoinGeckoAssetPlatform(assetPlatformId, signal);
  if (!assetPlatform) return null;
  try {
    const fetchErc20Coin = await fetchFromCoingecko(`/api/v3/coins/${assetPlatform.id}/contract/${contractAddress.toLowerCase()}`, {
      signal
    });
    const res = await fetchErc20Coin.json();

    // if coin is not found, it's stated in the response's json
    if (res.error) throw new Error(res.error);
    return res;
  } catch (error) {
    log.error("Can't fetch erc20 coingecko details", {
      error
    });
    return null;
  }
};

const getCoingeckoToken = async id => {
  try {
    const fetchErc20Coin = await fetchFromCoingecko(`/api/v3/coins/${id}`);
    return fetchErc20Coin.json();
  } catch (err) {
    // most likely invalid id
    return null;
  }
};

const getCoingeckoTokensList = async includePlatform => {
  const fetchErc20Coin = await fetchFromCoingecko(`/api/v3/coins/list?include_platform=${!!includePlatform}`);
  return fetchErc20Coin.json();
};

